-- Núcleo LF S3, juicios independientes Claude 18 PASS / 3 DEVOLVER.
-- Una transacción PG17; DESCARTADA por ruta gobernada; 0 deprecaciones legadas.
BEGIN;
DO $s3$
DECLARE p jsonb; cd text; hash_atestado text; hp text; ev jsonb; juicio jsonb; resultado jsonb;
        n int:=0; n_auto int:=0; n_manual int:=0; n_return int:=0; n_links int:=0;
        prev record; before_legacy jsonb; before_deprec jsonb; previous_replaced int;
BEGIN
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO before_legacy FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO before_deprec FROM lf_ops.nucleo_deprecaciones x;
 SELECT count(distinct legacy_id) INTO previous_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF previous_replaced<>56 OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>76
  OR (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>21
  OR (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586)
  OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
