e — juicio independiente comunicado 2026-11-23 21:22 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"S3-C19 queda canónica frente a S3-C10 por normalización de respuestas crudas y control de reintento ambiguo."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":523,"legada_codigo":"REG_CLIENT_PAYMENT_OUTCOME_NORMALIZATION_001","cobertura_esperada":"REEMPLAZADA","diferencias":"Especializa el contrato de reconciliación y reintento existente; diferencia entre fallo previo al envío y resultado ambiguo.","canonica":null},{"codigo":"S3-C20","eval_id":354,"hash_paquete_atestado":"47b92a53b01b0a0c4672cb537dba2ae22e108d08198d457ff773fbb59e4a4390","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:22 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"Solapa presentación de éxito S3-C06, pero S3-C20 gobierna acciones postpago independientes por deuda."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":524,"legada_codigo":"REG_CLIENT_PAYMENT_CONFIRMED_POST_ACTIONS_001","cobertura_esperada":"REEMPLAZADA","diferencias":"Desagrega efectos por deuda de la UI de éxito y no declara carta emitida sin integración del aliado.","canonica":null},{"codigo":"S3-C21","eval_id":355,"hash_paquete_atestado":"4461ada24460884c9f1c0bb4fcf2fcd35b064c7e688b8705b8cbbbc83db11ec0","version":1,"veredicto":"PASS","juez":"Claude — juicio independiente comunicado 2026-11-23 21:22 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":13126,"legada_codigo":"REG_CLIENT_PAYMENT_RECEIPT_REAL_EMAIL_001","cobertura_esperada":"REEMPLAZADA","diferencias":"La regla nueva cubre incidencia y origen de destinatario, sin sustituir dirección técnica Niubiz por correo ficticio.","canonica":null}]'::jsonb) LOOP
  cd:=p->>'codigo';
  SELECT id,hash_paquete,decision INTO prev FROM lf_ops.nucleo_evaluaciones
   WHERE regla=cd AND version=1 ORDER BY id DESC LIMIT 1;
  IF prev.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado'
     OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND prev.id IS DISTINCT FROM (p->>'eval_id')::bigint)
  THEN RAISE EXCEPTION 'S3_EVAL_DRIFT %',cd; END IF;
  IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8
   OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA')
  THEN RAISE EXCEPTION 'S3_NOT_CANDIDATE %',cd; END IF;
  hp:=lf_ops.nucleo_hash_paquete_v1(cd,1);
  IF hp IS DISTINCT FROM p->>'hash_paquete_atestado' THEN RAISE EXCEPTION 'S3_HASH_DRIFT %',cd; END IF;
  juicio:=jsonb_build_object('regla',cd,'hash_evaluado',hp,'veredicto',p->>'veredicto',
   'puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE',
   'revisor_es_productor',false,'llamadas_modelo',1,
   'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s3_juicios_independientes_v1.json#'||cd);
  BEGIN
   PERFORM lf_ops.nucleo_juicio_registrar_v1(juicio||jsonb_build_object('hash_evaluado',repeat('0',64)));
   RAISE EXCEPTION 'S3_HASH_NEGATIVE_ACCEPTED %',cd;
  EXCEPTION WHEN OTHERS THEN
   IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
  END;
  PERFORM lf_ops.nucleo_juicio_registrar_v1(juicio);
  ev:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
  IF p->>'veredicto'='DEVOLVER' THEN
    IF ev->>'decision'='AUTO' THEN RAISE EXCEPTION 'S3_RETURN_AUTO_ILLEGAL %',cd; END IF;
    resultado:=lf_ops.nucleo_version_descartar_v1(cd,'LEG-TECNICO',
      'JUICIO_INDEPENDIENTE_DEVOLVER: redundancia semántica con '||(p->>'canonica')||', decisión de Claude 2026-11-23 21:22 Lima');
    IF resultado->>'estado'<>'DESCARTADA' THEN RAISE EXCEPTION 'S3_DISCARD_FAILED %',cd; END IF;
    n_return:=n_return+1;
  ELSIF ev->>'decision'='AUTO' THEN
    resultado:=lf_ops.nucleo_regla_promover_v1(cd);
    IF resultado->>'resultado'<>'PROMOVIDA_AUTO'
      OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1)<>'PUBLICADA'
    THEN RAISE EXCEPTION 'S3_PROMOTION_FAILED % %',cd,resultado; END IF;
    n_auto:=n_auto+1;
  ELSE
    n_manual:=n_manual+1;
  END IF;
  n:=n+1;
  RAISE NOTICE 'S3_JUICIO % verdict=% score=% decision=%',cd,p->>'veredicto',ev->>'nota',ev->>'decision';
 END LOOP;
 IF n<>21 OR n_return<>3 OR n<>n_return+n_auto+n_manual
  OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S3-C%')<>21
  OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S3-C%' AND estado='DESCARTADA')<>3
  OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM before_legacy
  OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM before_deprec
 THEN RAISE EXCEPTION 'S3_JUICIO_FINAL_INVALID'; END IF;
 RAISE NOTICE 'S3_JUDGED_PASS total=% auto=% manual=% devueltas_descartadas=%',n,n_auto,n_manual,n_return;
END $s3$;
CREATE TEMP TABLE s3_cobertura ON COMMIT DROP AS
SELECT * FROM (VALUES
(183,'S3-C01','PARCIAL','Cobertura parcial de onboarding offline: conserva datos escritos y banner local; no cubre bloqueo del pago sin red.','Queda bloqueo de pago sin conexión con copy exacto en checkout.'),
(183,'S3-C02','REEMPLAZADA','Intención mixta cubierta conjuntamente por S3-C01 (datos de onboarding y banner local) y S3-C02 (CTA pago bloqueado, mensaje sin conexión); el texto datos guardados significa almacenamiento local, no persistencia remota.',''),
(185,'S3-C03','PARCIAL','Idempotencia protegida en onboarding mediante uuid_v4 y AUTH/IDEMPOTENCY_KEY_VALIDITY_MINUTES; no sustituye por sí sola idempotencia del checkout.','Falta idempotencia checkout, cubierta separadamente por S3-C04.'),
(185,'S3-C04','REEMPLAZADA','Intención mixta cubierta por S3-C03 onboarding y S3-C04 checkout con misma clave uuid_v4, política de expiración y no duplicación. Diferencia: ante vencimiento se requiere reconciliación segura, no repetición del cobro.',''),
(208,'S3-C05','REEMPLAZADA','La nueva regla exige bloqueo inmediato del primer clic CTA y no reabrir ante error ambiguo; complementa el control backend REG_CHK_004 de outcomes seguros y reserva/quote.',''),
(209,'S3-C06','REEMPLAZADA','La nueva regla exige resultado confirmado y fuente ledger en presentación, y procesos por deuda tras pago; S3-C20 especializa los efectos backend y evita confundir cuota inicial con liquidación.',''),
(210,'S3-C07','REEMPLAZADA','La legada nombra porcentajes históricos en duro y prohíbe letra pequeña; el núcleo obliga legibilidad de comisiones y toma precios vigentes de configuración del aliado, sin valores incrustados.',''),
(212,'S3-C08','REEMPLAZADA','La nueva regla exige SETTLED_CONFIRMED, ciclo NOT_ELIGIBLE a AVAILABLE y descarga exclusivamente AVAILABLE; el texto no anticipa emisión por pago inicial ni reemplaza integración del aliado.',''),
(226,'S3-C09','REEMPLAZADA','La legada nombra dos porcentajes históricos fijos; la canónica exige comisiones Niubiz/LF visibles y conciliadas dentro del total, usando configuración vigente del aliado.',''),
(228,'S3-C19','REEMPLAZADA','S3-C10 descartada por duplicar normalización; S3-C19 cubre intención de REG_NIU_004: error/timeout/callback ambiguo produce PAYMENT_PENDING_CONFIRMATION y bloquea reintento; aprobación y rechazo requieren evidencia autoritativa.',''),
(276,'S3-C11','REEMPLAZADA','La canónica exige checkbox con copy literal de REG_CHK_013, autorización y evidencia server-side previa al cobro automático; la salvedad de medios manuales evita exigir autorización por un débito que no existe.',''),
(277,'S3-C12','REEMPLAZADA','La regla combina derecho a cancelar recurrencia desde Mis operaciones sin penalidad y obligación distinta de SETTLED_CONFIRMED para emitir carta. Cancelar el débito no liquida deuda.',''),
(280,'S3-C13','REEMPLAZADA','Copy literal de REG_CHK_017 en resumen lateral de cuotas; difiere del copy sección Documentos de REG_SUC_004 (S3-C18). Carta solo después de SETTLED_CONFIRMED, nunca cuota inicial.',''),
(288,'S3-C11','REEMPLAZADA','S3-C14 descartada por duplicación. S3-C11 es canónica del checkbox literal de REG_CHK_CUO_005 y bloqueo del botón Pagar sin autorización explícita del medio de débito automático.',''),
(289,'S3-C15','REEMPLAZADA','Complementa cancelación sin penalidad publicada con obligación de informar visiblemente antes de pagar cuotas recurrentes; no equipara cancelar cobros futuros con condonar deuda.',''),
(292,'S3-C13','REEMPLAZADA','S3-C16 descartada por duplicar copy de REG_CHK_CUO_009; S3-C13 aplica el texto aprobado en resumen lateral de cuotas y bloqueo de promesa/carta por cuota inicial.',''),
(316,'S3-C17','REEMPLAZADA','La legada exige dos rutas QR Yape y paso CONFIRMANDO; la nueva regla presenta escaneo y CTA Ya escaneé / Continuar sin afirmar PAYMENT_CONFIRMED antes de evidencia backend.',''),
(327,'S3-C18','REEMPLAZADA','Copy literal de REG_SUC_004 exclusivamente en sección Documentos con PENDIENTE y CTA de descarga oculto hasta AVAILABLE; distinto del copy de resumen lateral S3-C13.',''),
(523,'S3-C19','REEMPLAZADA','Esta es la regla canónica de normalización autoritativa de outcomes, frente a la C10 descartada. Cubre rechazos probados, timeout ambiguo y no reintento hasta reconciliación server-side.',''),
(524,'S3-C20','REEMPLAZADA','La regla nueva separa los efectos postpago por oferta/deuda, pago único liquidado, cuota inicial de plan, selección mixta y onboarding_completed inmutable; distinta de la presentación de éxito S3-C06.',''),
(13126,'S3-C21','REEMPLAZADA','Diferencia técnica: exige customer_email validado, separación de niubiz_technical_email, incidencia si falta destinatario y PAYMENT_CONFIRMED; no usa rebote o correo técnico como confirmación.','')
) AS x(legacy_id,nucleo_codigo,estado_cobertura,diferencias,residual);
DO $bridge$
DECLARE x record; hp text; n int:=0; n_partial int:=0; pub int; before_replaced int; after_replaced int;
BEGIN
 SELECT count(distinct legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 FOR x IN SELECT * FROM s3_cobertura ORDER BY legacy_id, nucleo_codigo LOOP
  SELECT count(*) INTO pub FROM lf_ops.nucleo_regla_versiones WHERE regla=x.nucleo_codigo AND version=1 AND estado='PUBLICADA';
  IF pub<>1 THEN
   RAISE NOTICE 'S3_SKIP_NOT_PUBLICADA %/%',x.legacy_id,x.nucleo_codigo;
   CONTINUE;
  END IF;
  IF (x.legacy_id=183 AND x.estado_cobertura='REEMPLAZADA')
    AND NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla='S3-C01' AND version=1 AND estado='PUBLICADA')
  THEN RAISE EXCEPTION 'S3_MIXED_OFFLINE_INCOMPLETE'; END IF;
  IF (x.legacy_id=185 AND x.estado_cobertura='REEMPLAZADA')
    AND NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla='S3-C03' AND version=1 AND estado='PUBLICADA')
  THEN RAISE EXCEPTION 'S3_MIXED_IDEMPOTENCY_INCOMPLETE'; END IF;
  hp:=lf_ops.nucleo_hash_paquete_v1(x.nucleo_codigo,1);
  INSERT INTO lf_ops.lf_nucleo_cobertura_legada
  (legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
  VALUES(x.legacy_id,x.nucleo_codigo,1,x.estado_cobertura,x.diferencias,
    jsonb_build_object('fuente','lf_ops.v_reglas_compat_v1/'||x.legacy_id,
      'contraste','LEGADA: '||(SELECT descripcion FROM lf_ops.v_reglas_compat_v1 WHERE id=x.legacy_id)
        ||' NUCLEO PUBLICADO: '||(SELECT descripcion FROM lf_ops.nucleo_regla_versiones WHERE regla=x.nucleo_codigo AND version=1)
        ||' DIFERENCIA: '||x.diferencias,
      'residual',x.residual,'juicio','CLAUDE_INDEPENDIENTE_S3','fuente_juicio','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s3_juicios_independientes_v1.json'),
     hp,'GPT-6 / Claude juicio 2026-11-23 21:22');
  n:=n+1;
  IF x.estado_cobertura='PARCIAL' THEN n_partial:=n_partial+1; END IF;
 END LOOP;
 SELECT count(distinct legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S3-C%' AND estado='PUBLICADA')=18
   AND (n<>21 OR n_partial<>2 OR after_replaced<>before_replaced+19)
 THEN RAISE EXCEPTION 'S3_BRIDGE_FINAL_DRIFT: links % partial % baseline % final %',n,n_partial,before_replaced,after_replaced; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0 OR (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586) THEN
  RAISE EXCEPTION 'S3_LEGACY_CHANGED'; END IF;
 RAISE NOTICE 'S3_BRIDGE_PASS links=% partial_links=% replaced_total=%',n,n_partial,after_replaced;
END $bridge$;
COMMIT;
